mapper.select:
/* SQL-ID : isry.itgcms.sysmgmt.userauth.mapper.UserAuthAplyMapper.selectUserAuthAplyList : 사용자별 권한 신청 목록 조회 */
SELECT A.APLY_SN /* 신청일련번호 */ , A.USER_ID /* 사용자아이디 */ , C##RG.DEC_B64(C.FLNM_ENCPT) AS USER_FLNM /* 사용자성명 */ , A.INST_NO AS APLY_INST_NO /* 신청기관번호 */ , (SELECT INST_NM FROM TMP_APRV_INST WHERE INST_NO = A.INST_NO) AS APLY_INST_NM /* 신청기관명 */ , A.APRV_STTS_SE_CD /* 승인상태구분코드 */ , CASE WHEN A.APRV_STTS_SE_CD IS NULL THEN '' ELSE ( SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'APRV_STTS_SE_CD' /* 공통코드아이디 */ AND CMMNS_CD_VALUE = A.APRV_STTS_SE_CD /* 승인상태구분코드 */ AND USE_YN = 'Y' /* 공통코드_사용여부 */ ) END AS APRV_STTS_SE_NM /* 승인상태구분명 */ , A.APLY_TYPE_SE_CD /* 신청유형구분코드 */ , CASE WHEN A.APLY_TYPE_SE_CD IS NULL THEN '' ELSE ( SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'APLY_TYPE_SE_CD' /* 공통코드아이디 */ AND CMMNS_CD_VALUE = A.APLY_TYPE_SE_CD /* 신청유형구분코드 */ AND USE_YN = 'Y' /* 공통코드_사용여부 */ ) END AS APLY_TYPE_SE_NM /* 신청유형구분명 */ , A.SYS_MNGR_YN /* 시스템관리자여부 */ , A.ADDTNG_CHG_INST_NO /* 추가변경기관번호 */ , (SELECT INST_NM FROM TMP_APRV_INST WHERE INST_NO = A.ADDTNG_CHG_INST_NO) AS ADDTNG_CHG_INST_NM /* 추가변경기관명 */ , A.ATFINO /* 첨부파일번호 */ , NVL(A.APLY_YMD, TO_CHAR(A.FRST_REG_DT, 'YYYYMMDD')) AS APLY_YMD /* 신청일자 */ , A.LAST_MDFCN_DT /* 최종수정일시 */ FROM SAB240 A /** 사용자별 권한 신청 */ , SAA200 B /** 사용자 */ , SCA100 C /** 종사자 */ WHERE 1=1 AND A.USER_ID = B.USER_ID /* 사용자아이디 */ AND B.ENFSN_NO = C.ENFSN_NO /* 종사자번호 */
ORDER BY A.APLY_SN DESC

mapper.delete:

        /* SQL-ID : isry.itgcms.sysmgmt.userauth.mapper.UserAuthAplyMapper.deleteUserAuthAplyByUserId : 사용자별 권한 신청 삭제 */
	    DELETE FROM SAB240  /** 사용자별 권한 신청 */
	    WHERE USER_ID = #{userId}   /* 삭제할 사용자아이디 */

mapper.update:
/* SQL-ID : isry.itgcms.sysmgmt.userauth.mapper.UserAuthAplyMapper.updateWorkerInfoByUserAuthAply : 종사자 정보 수정 (권한 신청 승인) */ UPDATE SCA100 /** 종사자 */
OGDP_INST_NO = #{OGDP_INST_NO}, /* 소속기관번호 */ OGDP_DEPT_CD = #{OGDP_DEPT_CD}, /* 소속부서코드 */ OGDP_DEPT_NM = #{OGDP_DEPT_NM}, /* 소속부서명 */ JBPS_SE_CD = #{JBPS_SE_CD}, /* 직위구분코드 */ JBPS_NM = #{JBPS_NM}, /* 직위명 */ PRVUSE_JOIN_SCRIN_YN = NVL(#{PRVUSE_JOIN_SCRIN_YN}, 'N'), /* 전용가입화면여부 */ PRVUSE_JOIN_SE_CD = #{PRVUSE_JOIN_SE_CD}, /* 전용가입구분코드 */ LAST_MDFR_ID = #{MDRF_ID}, /* 최종수정자아이디 */ LAST_MDFCN_DT = SYSDATE /* 최종수정일시 */
WHERE ENFSN_NO = ( SELECT ENFSN_NO /* 종사자번호 */ FROM SAA200 /** 사용자 */ WHERE 1=1 AND USER_ID = #{USER_ID} /* 사용자아이디 */ )

sql.if:
AND ( A.APLY_TYPE_SE_CD NOT IN ('06','07') AND A.INST_NO IN ( SELECT INST_NO /* 기관번호 */ FROM TMP_APRV_INST /** 승인기관 (임시테이블) */ WHERE 1=1 AND UP_INST_NO = #{APRV_INST_NO} OR UP_APRV_INST_NO = #{APRV_INST_NO} /* 승인기관번호 */
OR INST_NO = #{OGDP_INST_NO} /* 소속기관번호 */
) OR /* 기관변경 및 추가 신청 */ A.APLY_TYPE_SE_CD IN ('06','07') AND A.ADDTNG_CHG_INST_NO IN ( SELECT INST_NO /* 기관번호 */ FROM TMP_APRV_INST /** 승인기관 (임시테이블) */ WHERE 1=1 AND UP_INST_NO = #{APRV_INST_NO} OR UP_APRV_INST_NO = #{APRV_INST_NO} /* 승인기관번호 */
OR INST_NO = #{OGDP_INST_NO} /* 소속기관번호 */
) )
